class Component extends DCLogic {
  state = { ready: false };
  componentDidMount() { this.tick(); }
  componentWillUnmount() { clearTimeout(this._t); }
  tick() {
    if (window.AHV_CAMPAIGN_NINE && window.AHV_CAMPAIGN_NINE_RENDER && window.AHV_COLLECTION_RENDER) {
      const N = window.AHV_CAMPAIGN_NINE_RENDER;
      const R = N.resolveRoute(this.props.route);
      // Both paths get a head. A miss used to leave the document with no title and no lang at all.
      if (R) N.applyHead(R); else N.applyNotFoundHead(this.requestedRoute());
      this.setState({ ready: true });
      return;
    }
    this._t = setTimeout(() => this.tick(), 60);
  }
  componentDidUpdate(prev) {
    const N = window.AHV_CAMPAIGN_NINE_RENDER;
    if (N && this.state.ready && prev.route !== this.props.route) {
      const R = N.resolveRoute(this.props.route);
      if (R) N.applyHead(R); else N.applyNotFoundHead(this.requestedRoute());
    }
  }
  requestedRoute() {
    let q = null;
    try { q = new URLSearchParams(location.search).get('route'); } catch (e) {}
    return q || this.props.route || '';
  }
  renderVals() {
    const N = window.AHV_CAMPAIGN_NINE_RENDER;
    if (!this.state.ready || !N || !N.emptyVals) return { path: '', indexable: '', blockCount: '0', imageCount: '0', flags: [], h1El: null, bodyEl: null, formEl: null, canonical: '', robots: '', layoutFit: '', headingDecision: '', title: '', hasForm: false, route: null, notFound: false, found: false, requestedRoute: '', validRoutes: [], showBreadcrumb: false, crumbs: [], crumbLast: '', guard: () => {} /* preview-only nav guard neutralised for the published site */ };
    const R = N.resolveRoute(this.props.route);
    if (!R) return N.notFoundVals(this.requestedRoute());
    const guard = () => {}; /* preview-only nav guard neutralised for the published site */
    return N.nineVals(R, guard, 'narrow');
  }
}
